import{_ as g,C as E,o as l,c as B,a2 as a,b as i,w as r,a as s,E as e,a3 as n}from"./chunks/framework.BBdhqAg0.js";const d="/assets/layout.TiloWLJ8.png",f=JSON.parse('{"title":"IBS 워크스페이스 시작하기","description":"","frontmatter":{},"headers":[],"relativePath":"intro/getting-started.md","filePath":"intro/getting-started.md","lastUpdated":1793107177000}'),h={name:"intro/getting-started.md"};function C(u,t,c,m,A,p){const o=E("Mermaid");return l(),B("div",null,[t[2]||(t[2]=a('<h1 id="ibs-워크스페이스-시작하기" tabindex="-1">IBS 워크스페이스 시작하기 <a class="header-anchor" href="#ibs-워크스페이스-시작하기" aria-label="Permalink to &quot;IBS 워크스페이스 시작하기&quot;">​</a></h1><blockquote><p>**IBS (Intelligent Business System)**는 부동산 개발사업의 전 과정을 &#39;업무 (Issue)&#39;와 &#39;데이터 파이프라인&#39; 중심으로 관리하고 협업하는 디벨로퍼 전용 업무 플랫폼입니다.</p><p>이 문서는 신규 사용자가 시스템에 처음 접속하여 계정을 설정하고, 본인의 업무와 팀 워크스페이스에 참여하여 첫 업무를 시작하는 온보딩 과정을 안내합니다.</p></blockquote><h2 id="대상-사용자" tabindex="-1">대상 사용자 <a class="header-anchor" href="#대상-사용자" aria-label="Permalink to &quot;대상 사용자&quot;">​</a></h2><ul><li><strong>개발/사업관리 실무자</strong> - 부지 매입, 인허가, 공정 및 외주 협력사 관리, 현장 이슈 점검</li><li><strong>분양/영업 담당자</strong> - 동·호수 배치, 분양 계약 등록, 권리의무 승계 및 해약 관리</li><li><strong>수납/재무 담당자</strong> - 회차별 대금 수납, 연체료 계산, 자금 출납 및 사업 수지 분석</li><li><strong>임원 및 의사결정자</strong> - 전자결재 승인, 실시간 대시보드 및 사업 지표 모니터링</li></ul><h2 id="⚡-1일차-5분-퀵스타트-체크리스트" tabindex="-1">⚡ 1일차 5분 퀵스타트 체크리스트 <a class="header-anchor" href="#⚡-1일차-5분-퀵스타트-체크리스트" aria-label="Permalink to &quot;⚡ 1일차 5분 퀵스타트 체크리스트&quot;">​</a></h2><p>처음 로그인하셨다면, 원활한 업무를 위해 아래 3가지를 먼저 확인해 주세요.</p>',6)),(l(),i(n,null,{default:r(()=>[e(o,{id:"mermaid-42",class:"mermaid",graph:"flowchart%20LR%0A%20%20%20%20Step1%5B%221.%20%EB%82%B4%20%ED%94%84%EB%A1%9C%ED%95%84%20%ED%99%95%EC%9D%B8%3Cbr%3E(%EB%B9%84%EB%B0%80%EB%B2%88%ED%98%B8%20%26%20%EC%97%B0%EB%9D%BD%EC%B2%98)%22%5D%20--%3E%20Step2%5B%222.%20%EB%AA%A8%EB%B0%94%EC%9D%BC%20%EC%95%B1%20%EC%97%B0%EB%8F%99%3Cbr%3E(%EC%83%9D%EC%B2%B4%EC%9D%B8%EC%A6%9D%20%26%20%ED%91%B8%EC%8B%9C%20%EC%84%A4%EC%A0%95)%22%5D%0A%20%20%20%20Step2%20--%3E%20Step3%5B%223.%20%EB%8C%80%EC%8B%9C%EB%B3%B4%EB%93%9C%20%EC%A0%90%EA%B2%80%3Cbr%3E(%EB%82%B4%20%EC%97%85%EB%AC%B4%20%26%20%EA%B2%B0%EC%9E%AC%20%ED%98%84%ED%99%A9)%22%5D%0A"})]),fallback:r(()=>[...t[0]||(t[0]=[s(" Loading... ",-1)])]),_:1})),t[3]||(t[3]=a('<ol><li><strong>내 프로필 확인 및 비밀번호 변경</strong>: <ul><li>우측 상단 사용자 아바타를 클릭하고 <code>[내 정보 수정]</code>으로 이동합니다.</li><li>연락처 (휴대전화번호)가 정확한지 확인하고, 초기 비밀번호를 안전한 개인 비밀번호로 변경합니다.</li></ul></li><li><strong>모바일 앱 설치 및 생체인증 등록</strong>: <ul><li>외근이나 현장 방문 시에도 긴급 결재와 실시간 소통을 놓치지 않도록 사내 모바일 앱 (iOS / Android)을 설치합니다.</li><li>첫 로그인 후 <strong>생체인증 (Face ID / 지문)</strong> 및 <strong>푸시 알림</strong>을 허용해 두면 원터치로 빠르게 결재를 승인할 수 있습니다.</li></ul></li><li><strong>대시보드에서 &#39;내 업무&#39; 확인</strong>: <ul><li>로그인 직후 열리는 <a href="/intro/dashboard.html">대시보드</a>에서 나에게 할당된 업무 목록 (<code>내 업무</code>)과 결재 요청 문서 (<code>전자결재 현황</code>)를 확인합니다.</li></ul></li></ol><h2 id="시스템-접속-및-온보딩-3단계" tabindex="-1">시스템 접속 및 온보딩 3단계 <a class="header-anchor" href="#시스템-접속-및-온보딩-3단계" aria-label="Permalink to &quot;시스템 접속 및 온보딩 3단계&quot;">​</a></h2><p>IBS를 정상적으로 이용하기 위해서는 계정 생성 후 관리자의 <strong>인사 정보 연결 및 워크스페이스 권한 부여</strong>가 진행됩니다.</p>',3)),(l(),i(n,null,{default:r(()=>[e(o,{id:"mermaid-97",class:"mermaid",graph:"flowchart%20LR%0A%20%20%20%20A%5B%221.%20%EA%B3%84%EC%A0%95%20%EC%83%9D%EC%84%B1%3Cbr%3E(%EB%B3%B4%EC%95%88%20%EC%BD%94%EB%93%9C%20%EA%B0%80%EC%9E%85)%22%5D%20--%3E%20B%5B%222.%20%EC%9D%B8%EC%82%AC%2F%EB%B3%B4%EC%A7%81%20%EB%B0%9C%EB%A0%B9%3Cbr%3E(%EB%B6%80%EC%84%9C%C2%B7%EC%A7%81%EC%B1%85%20%EB%A7%A4%ED%95%91)%22%5D%0A%20%20%20%20B%20--%3E%20C%5B%223.%20%EC%9B%8C%ED%81%AC%EC%8A%A4%ED%8E%98%EC%9D%B4%EC%8A%A4%20%EC%B0%B8%EC%97%AC%3Cbr%3E(%EC%97%AD%ED%95%A0%C2%B7%EA%B6%8C%ED%95%9C%20%EB%B6%80%EC%97%AC)%22%5D%0A%20%20%20%20C%20--%3E%20D%5B%22%F0%9F%9A%80%20%EC%A0%84%EC%B2%B4%20%EA%B8%B0%EB%8A%A5%20%ED%99%9C%EC%84%B1%ED%99%94%3Cbr%3E(%EC%A0%84%EC%9E%90%EA%B2%B0%EC%9E%AC%C2%B7%ED%94%84%EB%A1%9C%EC%A0%9D%ED%8A%B8%20%EB%A9%94%EB%89%B4)%22%5D%0A"})]),fallback:r(()=>[...t[1]||(t[1]=[s(" Loading... ",-1)])]),_:1})),t[4]||(t[4]=a('<h3 id="_1단계-계정-생성-회원-가입" tabindex="-1">1단계: 계정 생성 (회원 가입) <a class="header-anchor" href="#_1단계-계정-생성-회원-가입" aria-label="Permalink to &quot;1단계: 계정 생성 (회원 가입)&quot;">​</a></h3><ul><li><strong>접속 주소</strong>: <a href="https://ibs.dyibs.com" target="_blank" rel="noreferrer">https://ibs.dyibs.com</a></li><li>메인 화면의 <strong>[회원가입]</strong> 링크를 클릭하여 아이디와 비밀번호를 등록합니다.</li><li>가입 시 사내 보안 코드인 **계정 생성코드 (<code>dyibs-staff</code>)**를 반드시 입력해야 가입이 완료됩니다.</li></ul><h3 id="_2단계-인사-정보-등록-및-보직-발령-인사-담당자-처리" tabindex="-1">2단계: 인사 정보 등록 및 보직 발령 (인사 담당자 처리) <a class="header-anchor" href="#_2단계-인사-정보-등록-및-보직-발령-인사-담당자-처리" aria-label="Permalink to &quot;2단계: 인사 정보 등록 및 보직 발령 (인사 담당자 처리)&quot;">​</a></h3><ul><li>인사 담당자가 신규 가입 계정과 사내 인사 정보 (직원 카드)를 연결합니다.</li><li>소속 부서와 직책 (팀장, 담당 등)이 부여되면, <strong><a href="/approval/">전자결재 시스템</a>의 기안 양식 로드 및 자동 결재선 산출</strong> 기능이 자동으로 활성화됩니다.</li></ul><h3 id="_3단계-워크스페이스-초대-및-권한-부여-프로젝트-관리자-처리" tabindex="-1">3단계: 워크스페이스 초대 및 권한 부여 (프로젝트 관리자 처리) <a class="header-anchor" href="#_3단계-워크스페이스-초대-및-권한-부여-프로젝트-관리자-처리" aria-label="Permalink to &quot;3단계: 워크스페이스 초대 및 권한 부여 (프로젝트 관리자 처리)&quot;">​</a></h3><ul><li>담당 프로젝트나 본사 워크스페이스에 구성원으로 초대되고 역할 (권한)을 부여받습니다.</li><li>권한 설정이 완료되면 좌측 사이드바에 담당 프로젝트의 실무 메뉴 (계약, 수납, 부지 등)가 모두 활성화됩니다.</li></ul><h2 id="기본-화면-구성-ui-overview" tabindex="-1">기본 화면 구성 (UI Overview) <a class="header-anchor" href="#기본-화면-구성-ui-overview" aria-label="Permalink to &quot;기본 화면 구성 (UI Overview)&quot;">​</a></h2><p>로그인 후 마주치는 화면은 크게 3개의 핵심 영역으로 구성되어 있습니다.</p><div class="tip custom-block"><p class="custom-block-title">📸 실제 화면 안내</p><p><img src="'+d+'" alt="기본 화면 구성 (레이아웃)"></p></div><ol><li><strong>상단 헤더 바 (Header Bar)</strong>: <ul><li><strong>회사/프로젝트 선택기</strong>: 작업 대상 회사 및 프로젝트를 원클릭으로 전환</li><li><strong>알림 (Notice)</strong>: 나에게 할당된 업무 변경, 결재 요청, 공지사항 실시간 알림</li><li><strong>사내 메신저 아이콘</strong>: 실시간 <a href="/intro/chat.html">사내 메신저</a> 드로어 호출</li><li><strong>테마 및 사용자 메뉴</strong>: 라이트/다크 테마 전환 및 내 정보 수정</li></ul></li><li><strong>좌측 사이드바 (Navigation Drawer)</strong>: <ul><li><strong>업무 관리</strong>: 워크스페이스, 회의록, 로드맵, 업무 (이슈), 캘린더, 문서, 게시판</li><li><strong>본사 관리</strong>: 인사 조직 관리, 전자결재 시스템, 대외 공문 관리, 본사 회계 관리</li><li><strong>프로젝트 관리</strong>: 부지 관리, 유닛 설정, 계약 관리, 대금 수납, 분양 대행, 프로젝트 회계, 소송 관리</li></ul></li><li><strong>메인 작업 뷰 (Main View)</strong>: <ul><li>개인 맞춤형 위젯 기반의 <a href="/intro/dashboard.html">대시보드</a> 및 선택한 메뉴의 상세 업무 화면이 표시됩니다.</li></ul></li></ol><div class="tip custom-block"><p class="custom-block-title">📱 모바일 앱 (iOS / Android) 화면 구성 및 외근/현장 팁</p><ul><li><strong>상단 헤더 바 (Header Bar)</strong>: <ul><li><strong>전역 메신저 아이콘</strong>: 실시간 <a href="/intro/chat.html">사내 메신저</a> 목록으로 원터치 이동</li><li><strong>통합 알림 벨</strong>: 실시간 결재 요청, 업무 할당 알림 확인</li><li><strong>프로필</strong>: 다크 테마 설정 및 생체인증 관리</li></ul></li><li><strong>하단 네비게이션 탭 (Bottom Navigation Bar)</strong>: <ul><li><strong>홈 (Home)</strong>: 모바일 전용 요약 대시보드 (결재 대기, 진행 중 업무)</li><li><strong>업무 (Work)</strong>: 워크스페이스별 회의록 및 업무 (이슈) 관리</li><li><strong>프로젝트 (Project)</strong>: 사업지 현황 및 분양/계약 요약 조회</li><li><strong>소통 (Channel)</strong>: 사내 피드 및 부서별 소통 공간</li></ul></li><li><strong>현장 외근 시 유용한 기능</strong>: <ul><li>현장 실사 중 스마트폰 카메라로 <strong>현장 사진을 즉시 촬영하여 업무 (이슈)나 회의록에 첨부</strong>할 수 있습니다.</li><li>긴급 전자결재 요청 시 PC를 켤 필요 없이 <strong>Face ID / 지문 인증으로 1초 만에 승인</strong>할 수 있습니다. :::</li></ul></li></ul><h2 id="일일-권장-업무-루틴-daily-workflow" tabindex="-1">일일 권장 업무 루틴 (Daily Workflow) <a class="header-anchor" href="#일일-권장-업무-루틴-daily-workflow" aria-label="Permalink to &quot;일일 권장 업무 루틴 (Daily Workflow)&quot;">​</a></h2><ul><li><strong>09:00 (출근 &amp; 대시보드 점검)</strong>: <a href="/intro/dashboard.html">대시보드</a>에서 오늘의 일정 (캘린더), 나에게 할당된 업무, 결재 대기 문서를 확인합니다.</li><li><strong>11:00 (회의 및 협업)</strong>: <a href="/work-manage/meeting.html">회의록</a>을 통해 의제를 공유하고, 결정 사항에 따른 후속 조치 업무를 등록합니다.</li><li><strong>14:00 (실무 데이터 처리 &amp; 결재)</strong>: <a href="/contract/">계약 등록</a>, <a href="/payment/">수납 처리</a>를 수행하고 필요한 지출/품의 건은 <a href="/approval/draft.html">전자결재</a>로 상신합니다.</li><li><strong>18:00 (퇴근 전 진척률 갱신)</strong>: 오늘 진행한 작업의 <strong>업무 진척률</strong>과 작업 로그를 갱신하여 팀원들과 진행 상황을 투명하게 공유합니다.</li></ul><details class="details custom-block"><summary>⚙️ [관리자 및 PM 전용] 신규 프로젝트 초기 데이터 구축 5단계</summary><p>새로운 사업지나 프로젝트 워크스페이스를 처음 구축할 때는 다음 순서로 기초 데이터를 설정하는 것을 권장합니다.</p><ol><li><strong><a href="/project/">프로젝트 기본 정보 등록</a></strong>: 사업명, 사업 형태 (일반분양, 조합 등), 위치, 사업 기간 등 마스터 정보 설정</li><li><strong><a href="/project/units.html">상품 및 유닛 구성</a></strong>: 분양 대상 동·호수 배치와 타입별 전용/공급 면적, 층별 공급 가격 등록</li><li><strong><a href="/project/settings.html">분양 조건 및 예산 편성</a></strong>: 납부 회차별 비율 (계약금, 중도금, 잔금) 및 <a href="/project/budgets.html">사업 예산 항목</a> 설정</li><li><strong><a href="/project/site-manage.html">부지 관리 및 기존 계약 이관</a></strong>: 사업 부지 필지별 소유 현황 등록 및 기존 수분양자 계약·수납 데이터 이관</li><li><strong><a href="/work-manage/meeting.html">첫 회의록 작성 및 킥오프 업무 등록</a></strong>: 킥오프 회의록을 작성하여 결정 사항과 액션 아이템을 도출하고 첫 <a href="/work-manage/issue.html">업무 (Issue)</a> 발행</li></ol></details></div><h2 id="도움-요청-및-기술-지원" tabindex="-1">도움 요청 및 기술 지원 <a class="header-anchor" href="#도움-요청-및-기술-지원" aria-label="Permalink to &quot;도움 요청 및 기술 지원&quot;">​</a></h2><p>시스템 사용 중 문의사항이나 오류가 발생하면 아래 채널을 이용해 주세요.</p><ul><li><strong>사내 문의 게시판</strong>: <a href="https://ibs.dyibs.com/#/work/project/dyibs/forum/1" target="_blank" rel="noreferrer">IBS 기술지원 게시판</a></li><li><strong>담당 부서</strong>: IT·디지털혁신팀</li><li><strong>문의 요령</strong>: 오류 발생 화면 캡처, URL, 재현 경로를 함께 기재해 주시면 신속한 처리가 가능합니다.</li></ul>',14))])}const _=g(h,[["render",C]]);export{f as __pageData,_ as default};
